<template>
 <a-card :bordered="false">
  <div class="table-page-search-wrapper"><a-form layout="inline" @keyup.enter.native="load()"><a-row :gutter="24"><a-col :md="9" :sm="24"><a-form-item label="生产任务"><a-select v-model="taskId" allow-clear show-search option-filter-prop="children" style="width:340px" placeholder="请选择生产任务" @change="changeTask"><a-select-option v-for="t in options.tasks" :key="t.head_id" :value="t.head_id">{{t.number}} / {{t.order_number}}</a-select-option></a-select></a-form-item></a-col><a-col :md="6" :sm="24"><a-form-item label="单据编号"><a-input v-model="keyword" placeholder="领料单号或生产联系表号" /></a-form-item></a-col><a-col :md="5" :sm="24"><a-form-item label="状态"><a-select v-model="state" allow-clear placeholder="请选择状态" style="width:130px"><a-select-option v-for="(name,key) in states" :key="key" :value="key">{{name}}</a-select-option></a-select></a-form-item></a-col><a-col :md="4" :sm="24"><a-button type="primary" @click="load()">查询</a-button><a-button style="margin-left:8px" @click="resetQuery">重置</a-button></a-col></a-row></a-form></div>
  <div class="operator"><a-button type="primary" icon="plus" :disabled="!canCreate || !taskId" @click="create('issue')">开领料单</a-button><a-button :disabled="!canCreate || !taskId" @click="create('supplement')">开补料单</a-button><a-button :disabled="!managed(selected) || !selected || selected.kind==='return' || selected.workflow_status!=='confirmed'" @click="createReturn">关联退料</a-button><a-button :disabled="!editable(selected)" @click="open(selected,true)">编辑</a-button><a-button :disabled="!managed(selected) || !selected || !['draft','returned'].includes(selected.workflow_status)" @click="act('submit')">提交仓库</a-button><a-button :disabled="!options.canConfirm || !selected || selected.workflow_status!=='pending'" @click="act('confirm')">仓库确认</a-button><a-button :disabled="!options.canConfirm || !selected || selected.workflow_status!=='pending'" @click="act('reject')">退回修改</a-button><a-button :disabled="!managed(selected) || !selected || selected.workflow_status!=='pending'" @click="act('withdraw')">撤回修改</a-button><a-button :disabled="!managed(selected) || !selected || !['draft','returned','pending','cancelled'].includes(selected.workflow_status)" @click="act('delete')">删除</a-button><a-button icon="reload" @click="load(false)">刷新</a-button></div>
  <a-alert type="info" show-icon style="margin-bottom:12px" message="主任手填原料需求，仓库确认后才扣减或增加实物库存。库存不足时不能确认；全部原料到齐后才可安排实际开工，开工记录将在后续模块接入。"/>
  <a-table :columns="columns" :data-source="rows" row-key="id" bordered size="middle" :loading="loading" :pagination="pagination" :scroll="{x:1200}" :row-selection="{type:'radio',selectedRowKeys:selectedKeys,onChange:keys=>selectedKeys=keys}" @change="onPage"><template slot="kind" slot-scope="v">{{kinds[v]}}</template><template slot="route" slot-scope="_,r">第{{r.line_no+1}}行 / 工序{{r.stage_no}} / {{workshops[r.workshop_no-1]}}</template><template slot="state" slot-scope="v,r"><a-tag>{{v==='confirmed'?(r.kind==='return'?'已退料入库':'已领料出库'):states[v]}}</a-tag></template><template slot="action" slot-scope="_,r"><a @click="open(r,false)">查看</a></template></a-table>
  <j-modal :visible="visible" :title="(editing?'填写':'查看')+kinds[form.kind]" fullscreen switchFullscreen :footer="null" :mask-closable="false" @cancel="visible=false"><a-spin :spinning="saving"><a-descriptions bordered size="small" :column="3"><a-descriptions-item label="单据编号">{{form.number || '保存后生成'}}</a-descriptions-item><a-descriptions-item label="生产联系表">{{source.number}}</a-descriptions-item><a-descriptions-item label="状态">{{states[form.workflow_status] || '新建'}}</a-descriptions-item><a-descriptions-item label="原领料单">{{form.referenceNumber || form.reference_number || '无'}}</a-descriptions-item><a-descriptions-item label="库存单据">{{form.ledger_number || '尚未确认'}}</a-descriptions-item></a-descriptions>
   <div class="label">产品、工序与领料车间 *</div><a-select v-model="form.route" :disabled="!editing || form.kind==='return'" style="width:100%" placeholder="选择主任已安排的产品、工序和车间"><a-select-option v-for="route in routes" :key="route.key" :value="route.key">{{route.label}}</a-select-option></a-select>
   <h3>原料明细</h3><p>原料数量使用商品档案基本单位。库存查询不占用库存，仓库确认时会重新校验。</p><div class="table-scroll"><table class="details"><thead><tr><th>原料（商品档案）</th><th>单位</th><th>仓库</th><th>批号</th><th>数量</th><th>库存 / 可退数量</th><th v-if="editing">操作</th></tr></thead><tbody><tr v-for="(line,i) in form.lines" :key="i"><td><a-select v-if="editing && form.kind!=='return'" v-model="line.barCode" show-search option-filter-prop="children" style="width:300px" @change="chooseProduct(line)"><a-select-option v-for="p in options.products" :key="p.barCode" :value="p.barCode">{{product(p)}} / {{p.unit}}</a-select-option></a-select><span v-else>{{product(line)}}</span></td><td>{{line.unit}}</td><td><a-select v-if="editing" v-model="line.depotId" style="width:150px" @change="changeDepot(line)"><a-select-option v-for="d in options.depots" :key="d.id" :value="d.id">{{d.name}}</a-select-option></a-select><span v-else>{{depotName(line.depotId)}}</span></td><td><a-select v-if="editing && form.kind!=='return'" v-model="line.batchNumber" :disabled="!line.batchEnabled || !line.depotId" show-search style="width:280px" placeholder="选择库存批次" @change="chooseBatch(line)"><a-select-option v-for="batch in (line.batches||[])" :key="batch.batchNumber" :value="batch.batchNumber">{{batch.batchNumber}} / 可用 {{batch.available}} {{line.unit}}</a-select-option></a-select><span v-else>{{line.batchNumber || '无批号'}}</span></td><td><a-input-number v-if="editing" v-model="line.quantity" :min="0" :precision="6" style="width:130px"/><span v-else>{{line.quantity}}</span></td><td><template v-if="form.kind==='return'">{{line.maxReturn===undefined?'按原单核对':line.maxReturn}} {{line.unit}}</template><template v-else><a @click="checkStock(line)">查询库存</a><div v-if="line.stock">实物 {{line.stock.physical}} / 已预留 {{line.stock.reserved}} / 可用 {{line.stock.available}} {{line.unit}}</div></template></td><td v-if="editing"><a @click="form.lines.splice(i,1)">移除</a></td></tr></tbody></table></div><a-button v-if="editing && form.kind!=='return'" icon="plus" style="margin-top:12px" @click="addLine">添加原料</a-button>
   <div class="label">{{form.kind==='issue'?'领料说明':'补料 / 退料原因（必填）'}}</div><a-textarea v-model="form.reason" :disabled="!editing" :rows="3" :max-length="2000"/>
   <template v-if="form.history && form.history.length"><h3>操作记录</h3><a-timeline><a-timeline-item v-for="(h,i) in form.history" :key="i">{{date(h.created_at)}}　{{h.actor_name}}　{{actions[h.action]}}　{{h.comment}}<details><summary>当次明细</summary><pre>{{JSON.stringify(JSON.parse(h.payload_json),null,2)}}</pre></details></a-timeline-item></a-timeline></template><div class="footer"><a-button @click="visible=false">关闭</a-button><a-button v-if="editing" type="primary" :loading="saving" @click="save">保存草稿</a-button></div>
  </a-spin></j-modal>
  <a-modal :visible="!!actionName" :title="actions[actionName]" :confirm-loading="saving" :width="800" @cancel="actionName=''" @ok="confirmAction"><p>{{actionRow.number}}　{{kinds[actionRow.kind]}}</p><a-alert v-if="actionName==='delete'" type="warning" show-icon message="确认删除这张未确认单据？删除后将从列表移除，不影响库存。"/><a-alert v-if="actionName==='confirm'" type="warning" show-icon :message="actionRow.kind==='return'?'确认已收到实物退料后入库。确认后不能直接删除或反审核。':'确认实际发料后扣减仓库库存。确认后不能直接删除或反审核，多领物料应另开退料单。'"/><p v-for="(line,i) in actionRow.lines" :key="i">{{product(line)}} / {{depotName(line.depotId)}} / {{line.batchNumber || '无批号'}}：{{line.quantity}} {{line.unit}}</p><a-textarea v-model="comment" :rows="3" :max-length="2000" :placeholder="actionName==='reject'?'退回原因必填':'经办说明（选填）'"/></a-modal>
 </a-card>
</template>
<script>
import {getAction,postAction} from '@/api/manage'
export default {
 name:'MaterialRequestList',data(){return {taskId:undefined,keyword:'',state:undefined,options:{tasks:[],products:[],depots:[]},source:{lines:[],plan:[]},rows:[],selectedKeys:[],pagination:{current:1,pageSize:10,total:0,showSizeChanger:true},loading:false,saving:false,visible:false,editing:false,form:{lines:[]},actionName:'',actionRow:{lines:[]},comment:'',workshops:['一车间','二车间','三车间'],kinds:{issue:'领料单',supplement:'补料单',return:'退料单'},states:{draft:'草稿',pending:'待仓库确认',returned:'已退回',confirmed:'已确认',cancelled:'已撤销'},actions:{create:'创建',edit:'修改',submit:'提交仓库',confirm:'仓库确认',reject:'退回修改',withdraw:'撤回修改',cancel:'撤销',delete:'删除'},columns:[{title:'单据编号',dataIndex:'number',width:240},{title:'类型',dataIndex:'kind',scopedSlots:{customRender:'kind'},width:90},{title:'生产联系表',dataIndex:'task_number',width:240},{title:'产品 / 工序 / 车间',key:'route',scopedSlots:{customRender:'route'},width:230},{title:'状态',dataIndex:'workflow_status',scopedSlots:{customRender:'state'},width:140},{title:'操作',key:'action',scopedSlots:{customRender:'action'},width:90}] }},
 computed:{canCreate(){return this.options.canRequest && (this.source.workshops||[]).some(w=>(this.options.workshopNos||[]).includes(w.workshop_no) && w.workflow_status==='scheduled')},selected(){return this.rows.find(row=>row.id===this.selectedKeys[0])},routes(){const seen=new Set();return (this.source.plan||[]).filter(row=>{const key=this.routeKey(row);if(this.editing && (!(this.options.workshopNos||[]).includes(row.workshopNo) || !(this.source.workshops||[]).some(w=>w.workshop_no===row.workshopNo && w.workflow_status==='scheduled')))return false;if(seen.has(key))return false;seen.add(key);return true}).map(row=>({key:this.routeKey(row),label:'第'+(row.lineNo+1)+'行 '+this.product(this.source.lines[row.lineNo])+' / 工序'+row.stageNo+' / '+this.workshops[row.workshopNo-1]}))}},
 created(){this.initialize()},watch:{'$route.query.taskId'(id){this.taskId=id?Number(id):undefined;this.changeTask()}},
 methods:{
  async request(path,data){const r=data===undefined?await getAction('/factoryMaterial'+path):await postAction('/factoryMaterial'+path,data);if(r.code!==200)throw new Error(r.message || (r.data&&r.data.message) || '操作失败');return r.data},error(e){this.$message.error(e.message || '请求失败')},product(line){return line?[line.name,line.brand,line.standard,line.model].filter(Boolean).join(' / '):''},depotName(id){const d=this.options.depots.find(row=>row.id===id);return d?d.name:'#'+id},date(value){return value?new Date(value).toLocaleString('zh-CN'):''},routeKey(row){return row.lineNo+'|'+row.stageNo+'|'+row.workshopNo},managed(row){return !!row && (this.options.workshopNos||[]).includes(row.workshop_no)},editable(row){return !!row && this.managed(row) && ['draft','returned'].includes(row.workflow_status)},
  async initialize(){try{this.options=await this.request('/options');this.taskId=this.$route.query.taskId?Number(this.$route.query.taskId):undefined;await this.changeTask()}catch(e){this.error(e)}},async changeTask(){try{this.source=this.taskId?await this.request('/source/'+this.taskId):{lines:[],plan:[]};await this.load()}catch(e){this.error(e)}},resetQuery(){this.keyword='';this.state=undefined;this.taskId=undefined;this.changeTask()},
  async load(reset=true){if(reset)this.pagination.current=1;this.loading=true;this.selectedKeys=[];try{const data=await this.request('/list?taskId='+(this.taskId||0)+'&keyword='+encodeURIComponent(this.keyword)+'&state='+encodeURIComponent(this.state||'')+'&page='+this.pagination.current+'&size='+this.pagination.pageSize);this.rows=data.rows;this.pagination.total=data.total}catch(e){this.error(e)}finally{this.loading=false}},onPage(p){this.pagination.current=p.current;this.pagination.pageSize=p.pageSize;this.load(false)},
  create(kind){this.form={taskId:this.taskId,kind,route:undefined,reason:'',lines:[],history:[]};this.addLine();this.editing=true;this.visible=true},addLine(){this.form.lines.push({barCode:undefined,unit:'',depotId:undefined,batchNumber:'',batchEnabled:false,quantity:null,stock:null,batches:[]})},chooseProduct(line){const p=this.options.products.find(row=>row.barCode===line.barCode);Object.assign(line,{...p,batchEnabled:p.enable_batch_number==='1',batchNumber:'',stock:null,batches:[]});this.loadBatches(line)},
  changeDepot(line){line.batchNumber='';line.stock=null;this.loadBatches(line)},
  async loadBatches(line){this.$set(line,'batches',[]);if(!line.barCode || !line.depotId)return;const barcode=line.barCode,depot=line.depotId;try{if(!line.batchEnabled){await this.checkStock(line);return}const batches=await this.request('/batches?barCode='+encodeURIComponent(barcode)+'&depotId='+depot);if(line.barCode!==barcode || line.depotId!==depot)return;this.$set(line,'batches',batches);if(line.batchNumber && !batches.some(b=>b.batchNumber===line.batchNumber)){line.batchNumber=undefined;line.stock=null}if(!line.batchNumber && batches.length===1)line.batchNumber=batches[0].batchNumber;this.chooseBatch(line)}catch(e){this.error(e)}},
  chooseBatch(line){this.$set(line,'stock',(line.batches||[]).find(b=>b.batchNumber===line.batchNumber)||null)},
  async checkStock(line){if(!line.barCode || !line.depotId || line.batchEnabled && !line.batchNumber){this.$message.warning('先选择原料、仓库和库存批次');return}try{const data=await this.request('/stock?barCode='+encodeURIComponent(line.barCode)+'&depotId='+line.depotId+'&batchNumber='+encodeURIComponent(line.batchNumber||''));this.$set(line,'stock',data)}catch(e){this.error(e)}},
  async open(row,editing){try{const d=await this.request('/'+row.id);this.source=d.task;this.form={...d,taskId:d.task_head_id,referenceId:d.reference_id,route:d.line_no+'|'+d.stage_no+'|'+d.workshop_no};this.editing=editing;this.visible=true;if(editing && d.kind!=='return')await Promise.all(this.form.lines.map(line=>this.loadBatches(line)))}catch(e){this.error(e)}},
  async createReturn(){try{const d=await this.request('/'+this.selected.id);this.source=d.task;const lines=d.lines.map((line,i)=>({...line,referenceLine:i,quantity:Number(line.quantity)-Number(d.returned[i]||0),maxReturn:Number(line.quantity)-Number(d.returned[i]||0)})).filter(line=>line.quantity>0);if(!lines.length){this.$message.warning('该单原料已全部退回');return}this.form={taskId:d.task_head_id,kind:'return',referenceId:d.id,referenceNumber:d.number,route:d.line_no+'|'+d.stage_no+'|'+d.workshop_no,lines,reason:'',history:[]};this.editing=true;this.visible=true}catch(e){this.error(e)}},
  async save(){if(!this.form.route || !this.form.lines.length || this.form.lines.some(line=>!line.barCode || !line.depotId || (line.batchEnabled && !line.batchNumber) || !(Number(line.quantity)>0))){this.$message.warning('请选择车间工序并填写完整原料明细');return}const [lineNo,stageNo,workshopNo]=this.form.route.split('|').map(Number);this.saving=true;try{await this.request('/save',{id:this.form.id,version:this.form.version,taskId:this.form.taskId,kind:this.form.kind,referenceId:this.form.referenceId,lineNo,stageNo,workshopNo,reason:this.form.reason,lines:this.form.lines.map(line=>({barCode:line.barCode,depotId:line.depotId,batchNumber:line.batchNumber||'',quantity:line.quantity,referenceLine:line.referenceLine}))});this.visible=false;this.$message.success('已保存草稿，请提交仓库确认');await this.load(false)}catch(e){this.error(e)}finally{this.saving=false}},
  async act(action){try{this.actionRow=await this.request('/'+this.selected.id);this.comment='';this.actionName=action}catch(e){this.error(e)}},async confirmAction(){this.saving=true;try{await this.request('/'+this.actionRow.id+(this.actionName==='delete'?'/delete':'/action'),{version:this.actionRow.version,action:this.actionName,comment:this.comment});this.actionName='';this.$message.success('操作成功');await this.load(false)}catch(e){this.error(e)}finally{this.saving=false}}
 }
}
</script>
<style scoped>
.operator{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.label{margin:15px 0 6px;font-weight:500}h3{margin:22px 0 12px}.table-scroll{overflow-x:auto}.details{width:100%;min-width:1200px;border-collapse:collapse}.details th,.details td{border:1px solid #e8e8e8;padding:9px;text-align:left}.details th{background:#fafafa}.footer{display:flex;gap:10px;justify-content:flex-end;margin:20px 0}pre{white-space:pre-wrap;max-height:300px;overflow:auto}
</style>
